// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {XBORNID as C} from "../src/XBORNID.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    C c;

    function setUp() public {
        c = new C();
    }

    function _test(address owner) internal {
        vm.assume(owner != address(0));
        vm.assume(c.distributionFinished() == false);
        try c.transferOwnership(owner) {} catch { return; }
        try c.XBornID() {} catch { return; }
        uint256 observed;
        try c.balanceOf(owner) returns (uint256 __r) { observed = __r; } catch { return; }
        uint256 expected;
        try c.totalDistributed() returns (uint256 __r) { expected = __r; } catch { return; }
        assertTrue(observed == expected);
    }

    function testFuzz_test(address owner) public {
        owner = address(uint160(bound(uint256(uint160(owner)), 0xffff + 1, type(uint160).max)));
        vm.assume(owner.code.length == 0 && owner != address(this) && owner != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && owner != 0x000000000000000000636F6e736F6c652e6c6f67 && owner != 0x4e59b44847b379578588920cA78FbF26c0B4956C && owner != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _test(owner);
    }

    receive() external payable {}
}
